package com.aistock.gateway;
import com.aistock.common.ApiExceptionHandler;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import org.springframework.http.ResponseEntity;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class QuestionProxyTest {
 @Test void exactPathsQueriesBodyLimitAndForgedIdentity()throws Exception{var c=mock(ForecastPublicClient.class);when(c.get(anyString(),anyMap(),anyMap())).thenReturn(ResponseEntity.ok("{}".getBytes()));var mvc=MockMvcBuilders.standaloneSetup(new QuestionApiProxyController(c,new ObjectMapper())).setControllerAdvice(new ApiExceptionHandler()).build();mvc.perform(get("/api/v1/stock-questions").param("analysisId","a").param("page","2").param("userId","forged").header("X-User-Id","forged")).andExpect(status().isOk());var q=ArgumentCaptor.forClass(Map.class);var h=ArgumentCaptor.forClass(Map.class);verify(c).get(eq("stock-questions"),q.capture(),h.capture());assertEquals(Map.of("analysisId","a","page","2"),q.getValue());assertFalse(h.getValue().containsKey("X-User-Id"));mvc.perform(post("/api/v1/stock-questions").content("x".repeat(2049))).andExpect(status().isPayloadTooLarge());assertTrue(ProxyHeaderPolicy.allowed("GET","/api/v1/stock-questions/operations/11111111-1111-4111-8111-111111111111"));assertFalse(ProxyHeaderPolicy.allowed("POST","/api/v1/stock-questions/operations/11111111-1111-4111-8111-111111111111"));}
}
